      getWifiNetworks: async function () {
        var wifi = require("node-wifi");
        wifi.init({
          iface: "wlanusb",
        });
        return new Promise((resolve, reject) => {
          console.log("Starting wifi scan");
          wifi.scan((error, networks) => {
            if (error) {
              console.error("Error scanning networks:", error);
              resolve([]);
            } else {
              console.log("Wifi scan completed successfully");

              // Create a Map to store unique networks
              const uniqueNetworks = new Map();

              networks.forEach((network) => {
                let strength;
                if (network.quality > 80) {
                  strength = "wifi-4";
                } else if (network.quality > 55) {
                  strength = "wifi-3";
                } else if (network.quality > 30) {
                  strength = "wifi-2";
                } else {
                  strength = "wifi-1";
                }

                // Create a unique key using SSID and first 15 chars of MAC
                const key = `${network.ssid}:${network.mac.substring(0, 15)}`;

                // If this key doesn't exist or the quality is higher, add/update the network
                if (
                  !uniqueNetworks.has(key) ||
                  network.quality > uniqueNetworks.get(key).quality
                ) {
                  uniqueNetworks.set(key, {
                    name: network.ssid,
                    strength: strength,
                    security: network.security,
                    quality: network.quality, // Keep this for comparison
                  });
                }
              });

              // Convert Map values to array
              const uniqueNetworksArray = Array.from(uniqueNetworks.values());

              // Remove the quality property as it's no longer needed in the final output
              uniqueNetworksArray.forEach((network) => delete network.quality);

              resolve(uniqueNetworksArray);
            }
          });
        });
      },
      connectToWifi: function (ssid, password) {
        var wifi = require("node-wifi");
        wifi.init({
          iface: "wlanusb",
        });
        // Return booleans, True if the connection is successful, otherwise return False
        return new Promise((resolve, reject) => {
          wifi.connect({ ssid: ssid, password: password }, (error) => {
            if (error) {
              console.error("Error connecting to wifi:", error);
              resolve(false);
            } else {
              console.log("Connected to wifi:", ssid);
              resolve(true);
            }
          });
        });
      },
