      allowInternetForMacMobile: function (macAddress, callback) {
        var res;
        // First, enable general internet sharing from wlan0 to wwan0
        res = cmd(
          "sudo iptables --append FORWARD --in-interface wlan0 --out-interface wwan0 -j ACCEPT && sudo iptables --append FORWARD --in-interface wwan0 --out-interface wlan0 -m state --state RELATED,ESTABLISHED -j ACCEPT && sudo iptables --table nat --append POSTROUTING --out-interface wwan0 -j MASQUERADE",
          (error, stdout, stderr) => {
            if (error) {
              console.error(
                `exec error during enabling internet sharing: ${error}`,
              );
              return callback(error);
            }
            console.log(`Internet sharing enabled via wwan0.`);
            // Allow internet only for the specified MAC address on wwan0
            var allowMacCommand = `sudo iptables -I FORWARD 1 -i wwan0 -m mac --mac-source ${macAddress} -j ACCEPT`;
            // Block all other MAC addresses from accessing the internet via wwan0.
            var blockOthersCommand = `sudo iptables -A FORWARD -i wwan0 -j DROP`;

            // Allow specific MAC
            res = cmd(allowMacCommand, (error, stdout, stderr) => {
              if (error) {
                console.error(
                  `exec error during allowing MAC ${macAddress} on WWAN: ${error}`,
                );
                return callback(error);
              }
              console.log(
                `Internet access allowed for MAC ${macAddress} on WWAN.`,
              );

              // Block all other MACs
              res = cmd(blockOthersCommand, (error, stdout, stderr) => {
                if (error) {
                  console.error(
                    `exec error during blocking other MACs on WWAN: ${error}`,
                  );
                  return callback(error);
                }
                console.log(
                  `Internet access blocked for other MAC addresses on WWAN.`,
                );

                // Save iptables rules
                cmd(
                  "sudo netfilter-persistent save",
                  (error, stdout, stderr) => {
                    if (error) {
                      console.error(
                        `exec error during saving iptables rules for WWAN: ${error}`,
                      );
                      return callback(error);
                    }
                    console.log(`iptables rules for WWAN saved.`);
                    callback(null);
                  },
                );
              });
            });
          },
        );
      },
